      waves[w].forEach(function(ty,i){queue.push([tick+4*i,w,i,ty]);});
      queue.sort(function(a,b){return a[0]-b[0]||a[1]-b[1]||a[2]-b[2];});
      delete waves[w];
    }
    while(queue.length&&queue[0][0]<=tick){var q=queue.shift();enemies.push(newEnemy(q[3],q[1],Math.floor(ET[q[3]][0]*mw(q[1])/1000),0));}
    var fell=false;
    for(var i=0;i<enemies.length;i++){var e=enemies[i];var sp=e.slow>0?Math.floor(e.speed*60/100):e.speed;e.progress+=sp;if(e.progress>=e.r.len){e.progress=e.r.len;baseHp-=ET[e.type][3];log.push([tick,"L",e.id,baseHp]);R_leaks.push([e.id,e.type]);enemies.splice(i,1);i--;if(baseHp<=0){log.push([tick,"F",wave,0]);fell=true;break;}}}
    if(fell){fallTick=tick;endTick=tick;if(rec)rec(tick,{enemies:enemies.map(function(e){var p=epos(e);return [e.id,e.type,p[0],p[1],e.hp/e.maxHp,e.slow>0?1:0,e.air];}),shots:[],heals:[],kills:[],leaks:R_leaks,acts:R_acts,gold:gold,baseHp:baseHp,wave:wave,turrets:turrets.map(function(t){return t?[t.ti,t.tier]:null;}),fell:true,next:waves[wave+1]||[]});break;}
    for(var i=0;i<enemies.length;i++){var e=enemies[i];e.age++;if(e.type=="mender"&&e.age%20==0){var p=epos(e);R_heals.push([p[0],p[1]]);for(var j=0;j<enemies.length;j++){var f=enemies[j];var q=epos(f);var dx=q[0]-p[0],dy=q[1]-p[1];if(dx*dx+dy*dy<=22500)f.hp=Math.min(f.maxHp,f.hp+Math.floor(f.maxHp*8/100));}}}
    for(var s=0;s<16;s++){var t=turrets[s];if(!t)continue;if(t.cd>0){t.cd--;if(t.cd>0)continue;}
      var b=TT[t.type],ts=tstats(t),cands=[];
      for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.air?!b[8]:!b[7])continue;var p=epos(e);var dx=p[0]-t.x,dy=p[1]-t.y;if(dx*dx+dy*dy<=ts.rg*ts.rg)cands.push(e);}
      if(!cands.length)continue;
      var tg=null;if(strat.target){var cv=cands.map(view);var id=strat.target({slot:s,type:t.type,tier:t.tier,x:t.x,y:t.y,range:ts.rg},cv);for(var i=0;i<cands.length;i++)if(cands[i].id===id){tg=cands[i];break;}}
      if(!tg){tg=cands[0];for(var i=1;i<cands.length;i++){if(cands[i].r.len-cands[i].progress<tg.r.len-tg.progress)tg=cands[i];}}
      var tp=epos(tg);var hits=[tg];
      if(b[4]>0){hits=[];for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.air?!b[8]:!b[7])continue;var p=epos(e);var dx=p[0]-tp[0],dy=p[1]-tp[1];if(dx*dx+dy*dy<=b[4]*b[4])hits.push(e);}}
      for(var i=0;i<hits.length;i++){var e=hits[i];e.hp-=b[6]?ts.d:Math.max(1,ts.d-e.armor);if(b[5])e.slow=b[5];}
      t.cd=b[2];
      R_shots.push([s,t.ti,tp[0],tp[1],tg.air]);
      var ne=[],born=[];for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.hp<=0){gold+=ET[e.type][2];log.push([tick,"K",e.id,s]);var p=epos(e);R_kills.push([e.id,e.type,p[0],p[1],e.air]);
        if(e.type=="splitter"){for(var k=0;k<3;k++)born.push(newEnemy("splitling",e.wave,Math.max(1,Math.floor(e.maxHp/4)),e.progress));}}else ne.push(e);}
      enemies=ne.concat(born);
    }
    for(var i=0;i<enemies.length;i++)if(enemies[i].slow>0)enemies[i].slow--;
    if(rec)rec(tick,{enemies:enemies.map(function(e){var p=epos(e);return [e.id,e.type,p[0],p[1],e.hp/e.maxHp,e.slow>0?1:0,e.air];}),shots:R_shots,heals:R_heals,kills:R_kills,leaks:R_leaks,acts:R_acts,gold:gold,baseHp:baseHp,wave:wave,turrets:turrets.map(function(t){return t?[t.ti,t.tier]:null;}),fell:false,next:(waves[wave+1]||[]).slice()});
  }
