  function mk(p){var pts=p.map(function(q){return [q[0]*100+50,q[1]*100+50];});var L=0;for(var i=1;i<pts.length;i++)L+=Math.abs(pts[i][0]-pts[i-1][0])+Math.abs(pts[i][1]-pts[i-1][1]);return {pts:pts,len:L};}
  var R=[mk(GP),mk(AP)];
  function pos(r,p){var pts=r.pts;for(var i=1;i<pts.length;i++){var a=pts[i-1],b=pts[i];var l=Math.abs(b[0]-a[0])+Math.abs(b[1]-a[1]);if(p<=l||i==pts.length-1){var q=Math.min(p,l);return [a[0]+Math.sign(b[0]-a[0])*q,a[1]+Math.sign(b[1]-a[1])*q];}p-=l;}}
  var SL=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  var TN=["bolt","cannon","frost","lance","flak"];
  var TT={bolt:[50,26,8,300,0,0,0,1,1],cannon:[90,60,24,260,90,0,0,1,0],frost:[70,10,12,240,0,30,0,1,1],lance:[120,180,36,360,0,0,1,1,0],flak:[80,40,10,320,70,0,0,0,1]};
  var ET={grunt:[60,10,4,1,0,1,10],runner:[40,20,4,1,0,2,4],wisp:[50,12,6,2,1,3,3],brute:[150,6,9,3,0,4,3],splitter:[90,8,6,2,0,6,2],mender:[70,8,7,2,0,8,1],splitling:[0,12,1,1,0,999,0]};
  var EO=["grunt","runner","wisp","brute","splitter","mender"];
  function armorOf(t,w){return t=="grunt"?Math.floor(w/4):t=="brute"?6+w:0;}
  var mcache=[0,1000];function mw(w){while(mcache.length<=w)mcache.push(Math.floor(mcache[mcache.length-1]*108/100));return mcache[w];}
  function mulberry32(a){return function(){a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return (t^(t>>>14))>>>0;};}
  var rng=mulberry32(seed);
  function gen(w){var n=4+Math.floor(3*w/5),out=[];var av=EO.filter(function(t){return ET[t][5]<=w;});var tw=0;av.forEach(function(t){tw+=ET[t][6];});for(var i=0;i<n;i++){var r=rng()%tw;for(var j=0;j<av.length;j++){if(r<ET[av[j]][6]){out.push(av[j]);break;}r-=ET[av[j]][6];}}return out;}
  var strat=createStrategy();
  var gold=250,baseHp=10,log=[],nextId=1,enemies=[],queue=[],turrets=[];for(var z=0;z<16;z++)turrets.push(null);
  var waves={1:gen(1)},wave=0,fallTick=-1,endTick=maxTicks;
  function newEnemy(type,w,maxHp,prog){var e=ET[type];var air=e[4];return {id:nextId++,type:type,hp:maxHp,maxHp:maxHp,armor:armorOf(type,w),speed:e[1],progress:prog,age:0,slow:0,wave:w,air:air,r:R[air]};}
  function epos(e){return pos(e.r,e.progress);}
  function view(e){var p=epos(e);return {id:e.id,type:e.type,hp:e.hp,maxHp:e.maxHp,x:p[0],y:p[1],air:e.air,armor:e.armor,speed:e.speed,slowed:e.slow>0?1:0,remaining:e.r.len-e.progress};}
  function tstats(t){var b=TT[t.type],d=b[1],rg=b[3];for(var i=1;i<t.tier;i++){d=Math.floor(d*16/10);rg+=30;}return {d:d,rg:rg};}
  for(var tick=0;tick<maxTicks;tick++){
    var R_shots=[],R_heals=[],R_kills=[],R_leaks=[],R_acts=[];
    if(tick>=20&&(tick-20)%40==0){
      wave=(tick-20)/40+1;var w=wave;
      gold+=Math.min(50,Math.floor(gold*5/100))+10+2*w;
      waves[w+1]=gen(w+1);
      var st={tick:tick,wave:w,gold:gold,baseHp:baseHp,slots:SL.map(function(s,i){var t=turrets[i];return {slot:i,x:s[0],y:s[1],turret:t?{type:t.type,tier:t.tier,spent:t.spent}:null};}),enemies:enemies.map(view),nextWave:waves[w+1].slice()};
      var acts=strat.plan(st);
      if(Array.isArray(acts))for(var ai=0;ai<acts.length&&ai<32;ai++){var a=acts[ai];if(!a||typeof a!="object")continue;var s=a.slot;if(typeof s!="number"||s<0||s>15||Math.floor(s)!==s)continue;var t,c;
        if(a.op=="build"){var ti=TN.indexOf(a.type);if(ti<0||turrets[s])continue;c=TT[a.type][0];if(gold<c)continue;gold-=c;turrets[s]={type:a.type,ti:ti,tier:1,spent:c,cd:0,slot:s,x:SL[s][0]*100+50,y:SL[s][1]*100+50};log.push([tick,"B",s,ti]);R_acts.push([s,"B",ti]);}
        else if(a.op=="upgrade"){t=turrets[s];if(!t||t.tier>=3)continue;c=TT[t.type][0]*t.tier;if(gold<c)continue;gold-=c;t.spent+=c;t.tier++;log.push([tick,"U",s,t.tier]);R_acts.push([s,"U",t.ti]);}
        else if(a.op=="sell"){t=turrets[s];if(!t)continue;gold+=Math.floor(t.spent*70/100);turrets[s]=null;log.push([tick,"S",s,0]);R_acts.push([s,"S",t.ti]);}}
      waves[w].forEach(function(ty,i){queue.push([tick+4*i,w,i,ty]);});
      queue.sort(function(a,b){return a[0]-b[0]||a[1]-b[1]||a[2]-b[2];});
      delete waves[w];
    }
    while(queue.length&&queue[0][0]<=tick){var q=queue.shift();enemies.push(newEnemy(q[3],q[1],Math.floor(ET[q[3]][0]*mw(q[1])/1000),0));}
    var fell=false;
    for(var i=0;i<enemies.length;i++){var e=enemies[i];var sp=e.slow>0?Math.floor(e.speed*60/100):e.speed;e.progress+=sp;if(e.progress>=e.r.len){e.progress=e.r.len;baseHp-=ET[e.type][3];log.push([tick,"L",e.id,baseHp]);R_leaks.push([e.id,e.type]);enemies.splice(i,1);i--;if(baseHp<=0){log.push([tick,"F",wave,0]);fell=true;break;}}}
    if(fell){fallTick=tick;endTick=tick;if(rec)rec(tick,{enemies:enemies.map(function(e){var p=epos(e);return [e.id,e.type,p[0],p[1],e.hp/e.maxHp,e.slow>0?1:0,e.air];}),shots:[],heals:[],kills:[],leaks:R_leaks,acts:R_acts,gold:gold,baseHp:baseHp,wave:wave,turrets:turrets.map(function(t){return t?[t.ti,t.tier]:null;}),fell:true,next:waves[wave+1]||[]});break;}
    for(var i=0;i<enemies.length;i++){var e=enemies[i];e.age++;if(e.type=="mender"&&e.age%20==0){var p=epos(e);R_heals.push([p[0],p[1]]);for(var j=0;j<enemies.length;j++){var f=enemies[j];var q=epos(f);var dx=q[0]-p[0],dy=q[1]-p[1];if(dx*dx+dy*dy<=22500)f.hp=Math.min(f.maxHp,f.hp+Math.floor(f.maxHp*8/100));}}}
    for(var s=0;s<16;s++){var t=turrets[s];if(!t)continue;if(t.cd>0){t.cd--;if(t.cd>0)continue;}
      var b=TT[t.type],ts=tstats(t),cands=[];
      for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.air?!b[8]:!b[7])continue;var p=epos(e);var dx=p[0]-t.x,dy=p[1]-t.y;if(dx*dx+dy*dy<=ts.rg*ts.rg)cands.push(e);}
      if(!cands.length)continue;
      var tg=null;if(strat.target){var cv=cands.map(view);var id=strat.target({slot:s,type:t.type,tier:t.tier,x:t.x,y:t.y,range:ts.rg},cv);for(var i=0;i<cands.length;i++)if(cands[i].id===id){tg=cands[i];break;}}
      if(!tg){tg=cands[0];for(var i=1;i<cands.length;i++){if(cands[i].r.len-cands[i].progress<tg.r.len-tg.progress)tg=cands[i];}}
      var tp=epos(tg);var hits=[tg];
      if(b[4]>0){hits=[];for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.air?!b[8]:!b[7])continue;var p=epos(e);var dx=p[0]-tp[0],dy=p[1]-tp[1];if(dx*dx+dy*dy<=b[4]*b[4])hits.push(e);}}
      for(var i=0;i<hits.length;i++){var e=hits[i];e.hp-=b[6]?ts.d:Math.max(1,ts.d-e.armor);if(b[5])e.slow=b[5];}
      t.cd=b[2];
      R_shots.push([s,t.ti,tp[0],tp[1],tg.air]);
      var ne=[],born=[];for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.hp<=0){gold+=ET[e.type][2];log.push([tick,"K",e.id,s]);var p=epos(e);R_kills.push([e.id,e.type,p[0],p[1],e.air]);
        if(e.type=="splitter"){for(var k=0;k<3;k++)born.push(newEnemy("splitling",e.wave,Math.max(1,Math.floor(e.maxHp/4)),e.progress));}}else ne.push(e);}
      enemies=ne.concat(born);
    }
    for(var i=0;i<enemies.length;i++)if(enemies[i].slow>0)enemies[i].slow--;
    if(rec)rec(tick,{enemies:enemies.map(function(e){var p=epos(e);return [e.id,e.type,p[0],p[1],e.hp/e.maxHp,e.slow>0?1:0,e.air];}),shots:R_shots,heals:R_heals,kills:R_kills,leaks:R_leaks,acts:R_acts,gold:gold,baseHp:baseHp,wave:wave,turrets:turrets.map(function(t){return t?[t.ti,t.tier]:null;}),fell:false,next:(waves[wave+1]||[]).slice()});
  }
  var js=JSON.stringify(log),h=0x811c9dc5;for(var i=0;i<js.length;i++){h^=js.charCodeAt(i);h=Math.imul(h,0x01000193);}
  return {score:Math.round((endTick-20)/40*100)/100,fallTick:fallTick,log:log,hash:("0000000"+(h>>>0).toString(16)).slice(-8)};
}

