function createStrategy() {
  var T = {
    bolt:   { c: 50,  d: 26,  p: 8,  r: 300, sp: 0,  sl: 0,  pi: 0, g: 1, a: 1 },
    cannon: { c: 90,  d: 60,  p: 24, r: 260, sp: 90, sl: 0,  pi: 0, g: 1, a: 0 },
    frost:  { c: 70,  d: 10,  p: 12, r: 240, sp: 0,  sl: 30, pi: 0, g: 1, a: 1 },
    lance:  { c: 120, d: 180, p: 36, r: 360, sp: 0,  sl: 0,  pi: 1, g: 1, a: 0 },
    flak:   { c: 80,  d: 40,  p: 10, r: 320, sp: 70, sl: 0,  pi: 0, g: 0, a: 1 }
  };
  var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var BASE = { grunt: 60, runner: 40, wisp: 50, brute: 150, splitter: 90, mender: 70 };
  function pts(p) {
    var out = [];
    for (var i = 1; i < p.length; i++) {
      var ax = p[i-1][0]*100+50, ay = p[i-1][1]*100+50, bx = p[i][0]*100+50, by = p[i][1]*100+50;
      var L = Math.abs(bx-ax)+Math.abs(by-ay);
      for (var q = 0; q < L; q += 25) out.push([ax + Math.sign(bx-ax)*q, ay + Math.sign(by-ay)*q]);
    }
    return out;
  }
  var GS = pts([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AS = pts([[0,6],[21,6],[21,11],[23,11]]);
  var covCache = {};
  function cov(x, y, r, air) {
    var k = x + "," + y + "," + r + "," + air;
    if (covCache[k] !== undefined) return covCache[k];
    var S = air ? AS : GS, n = 0, cx = x*100+50, cy = y*100+50;
    for (var i = 0; i < S.length; i++) { var dx = S[i][0]-cx, dy = S[i][1]-cy; if (dx*dx+dy*dy <= r*r) n++; }
    covCache[k] = n; return n;
  }
  function stats(type, tier) { var d = T[type].d, r = T[type].r; for (var i = 1; i < tier; i++) { d = Math.floor(d*16/10); r += 30; } return { d: d, r: r }; }
  function mult(w) { var m = 1000; for (var i = 2; i <= w; i++) m = Math.floor(m*108/100); return m; }
  // value of a turret against the expected mix
  function value(type, tier, sl, mix, frostCount) {
    var t = T[type], s = stats(type, tier), v = 0;
    for (var i = 0; i < mix.length; i++) {
      var e = mix[i];
      if (e.air ? !t.a : !t.g) continue;
      var c = cov(sl.x, sl.y, s.r, e.air);
      var dmg = t.pi ? s.d : Math.max(1, s.d - e.armor);
      dmg = Math.min(dmg, e.hp);
      if (t.sp) dmg *= (e.air ? 1.5 : 1.8);
      v += dmg * c / t.p / e.hp * e.w;
    }
    if (t.sl) v = v * 1 + (frostCount < 2 ? 0.5 : 0.1) * v + 0.02 * (frostCount < 2 ? 1 : 0);
    return v;
  }
  return {
    plan: function (st) {
      var w = st.wave + 1, m = mult(w), mix = [], counts = {};
      for (var i = 0; i < st.nextWave.length; i++) counts[st.nextWave[i]] = (counts[st.nextWave[i]] || 0) + 1;
      for (var k in counts) {
        var hp = Math.floor(BASE[k]*m/1000);
        var armor = k === "grunt" ? Math.floor(w/4) : k === "brute" ? 6 + w : 0;
        var lw = k === "brute" ? 3 : (k === "wisp" || k === "splitter" || k === "mender") ? 2 : 1;
        mix.push({ air: k === "wisp" ? 1 : 0, hp: hp, armor: armor, w: counts[k] * hp * (1 + 0.3*lw) });
        if (k === "splitter") mix.push({ air: 0, hp: Math.max(1, Math.floor(hp/4)), armor: 0, w: counts[k]*3*Math.max(1,Math.floor(hp/4)) });
      }
      // normalise by total hp so value is "fraction of wave killed"
      var gold = st.gold, acts = [], slots = st.slots.map(function (s) { return { slot: s.slot, x: s.x, y: s.y, t: s.turret ? { type: s.turret.type, tier: s.turret.tier, spent: s.turret.spent } : null }; });
      for (var iter = 0; iter < 32; iter++) {
        var fc = 0; slots.forEach(function (s) { if (s.t && s.t.type === "frost") fc++; });
        var best = null;
        for (var j = 0; j < slots.length; j++) {
          var s = slots[j];
          if (!s.t) {
            for (var q = 0; q < TYPES.length; q++) {
              var ty = TYPES[q], c = T[ty].c, v = value(ty, 1, s, mix, fc) ;
              var r = v / c;
              if (!best || r > best.r) best = { r: r, c: c, act: { op: "build", slot: j, type: ty }, s: s, ty: ty };
            }
          } else if (s.t.tier < 3) {
            var c2 = T[s.t.type].c * s.t.tier;
            var dv = value(s.t.type, s.t.tier+1, s, mix, fc) - value(s.t.type, s.t.tier, s, mix, fc);
            var r2 = dv / c2 * 1.1;
            if (!best || r2 > best.r) best = { r: r2, c: c2, act: { op: "upgrade", slot: j }, s: s };
          }
        }
        if (!best) {
          // all full and maxed: replace weakest
          var worst = null;
          for (var j2 = 0; j2 < slots.length; j2++) {
            var s2 = slots[j2]; var cur = value(s2.t.type, 3, s2, mix, fc);
            for (var q2 = 0; q2 < TYPES.length; q2++) {
              var ty2 = TYPES[q2]; if (ty2 === s2.t.type) continue;
              var gain = value(ty2, 3, s2, mix, fc - (s2.t.type === "frost" ? 1 : 0)) - cur;
              if (gain > 0 && (!worst || gain > worst.g)) worst = { g: gain, s: s2, ty: ty2 };
            }
          }
          if (worst && gold + Math.floor(worst.s.t.spent*70/100) >= T[worst.ty].c * 4) {
            acts.push({ op: "sell", slot: worst.s.slot }); gold += Math.floor(worst.s.t.spent*70/100);
            acts.push({ op: "build", slot: worst.s.slot, type: worst.ty }); gold -= T[worst.ty].c;
            worst.s.t = { type: worst.ty, tier: 1, spent: T[worst.ty].c };
            continue;
          }
          break;
        }
        if (best.c > gold) break;
        gold -= best.c; acts.push(best.act);
        if (best.act.op === "build") best.s.t = { type: best.ty, tier: 1, spent: best.c };
        else { best.s.t.spent += best.c; best.s.t.tier++; }
      }
      return acts;
    },
    target: function (tu, cands) {
      var t = T[tu.type], d = stats(tu.type, tu.tier).d, best = null, bs = -1;
      for (var i = 0; i < cands.length; i++) {
        var e = cands[i], sc;
        if (t.sp) {
          var n = 0;
          for (var j = 0; j < cands.length; j++) { var dx = cands[j].x - e.x, dy = cands[j].y - e.y; if (dx*dx+dy*dy <= t.sp*t.sp) n += Math.min(cands[j].hp, Math.max(1, d - cands[j].armor)); }
          sc = n * 10000 - e.remaining;
        } else if (t.sl) {
          sc = (e.slowed ? 0 : 1e7) + e.maxHp * 10 - e.remaining / 100;
        } else {
          var eff = t.pi ? d : Math.max(1, d - e.armor);
          sc = Math.min(eff, e.hp) * 10000 - e.remaining;
          if (e.type === "mender") sc += 5000 * 10;
        }
        if (sc > bs) { bs = sc; best = e.id; }
      }
      return best;
    }
  };
}

