    frost:  { c: 70,  d: 10,  p: 12, r: 240, sp: 0,  sl: 30, pi: 0, g: 1, a: 1 },
    lance:  { c: 120, d: 180, p: 36, r: 360, sp: 0,  sl: 0,  pi: 1, g: 1, a: 0 },
    flak:   { c: 80,  d: 40,  p: 10, r: 320, sp: 70, sl: 0,  pi: 0, g: 0, a: 1 }
  };
  var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var BASE = { grunt: 60, runner: 40, wisp: 50, brute: 150, splitter: 90, mender: 70 };
  function pts(p) {
    var out = [];
    for (var i = 1; i < p.length; i++) {
      var ax = p[i-1][0]*100+50, ay = p[i-1][1]*100+50, bx = p[i][0]*100+50, by = p[i][1]*100+50;
      var L = Math.abs(bx-ax)+Math.abs(by-ay);
      for (var q = 0; q < L; q += 25) out.push([ax + Math.sign(bx-ax)*q, ay + Math.sign(by-ay)*q]);
    }
    return out;
  }
  var GS = pts([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AS = pts([[0,6],[21,6],[21,11],[23,11]]);
  var covCache = {};
  function cov(x, y, r, air) {
    var k = x + "," + y + "," + r + "," + air;
    if (covCache[k] !== undefined) return covCache[k];
    var S = air ? AS : GS, n = 0, cx = x*100+50, cy = y*100+50;
    for (var i = 0; i < S.length; i++) { var dx = S[i][0]-cx, dy = S[i][1]-cy; if (dx*dx+dy*dy <= r*r) n++; }
    covCache[k] = n; return n;
  }
  function stats(type, tier) { var d = T[type].d, r = T[type].r; for (var i = 1; i < tier; i++) { d = Math.floor(d*16/10); r += 30; } return { d: d, r: r }; }
  function mult(w) { var m = 1000; for (var i = 2; i <= w; i++) m = Math.floor(m*108/100); return m; }
  // value of a turret against the expected mix
  function value(type, tier, sl, mix, frostCount) {
