        var lw = k === "brute" ? 3 : (k === "wisp" || k === "splitter" || k === "mender") ? 2 : 1;
        mix.push({ air: k === "wisp" ? 1 : 0, hp: hp, armor: armor, w: counts[k] * hp * (1 + 0.3*lw) });
