        else { best.s.t.spent += best.c; best.s.t.tier++; }
      }
      return acts;
    },
    target: function (tu, cands) {
      var t = T[tu.type], d = stats(tu.type, tu.tier).d, best = null, bs = -1;
      for (var i = 0; i < cands.length; i++) {
        var e = cands[i], sc;
        if (t.sp) {
          var n = 0;
          for (var j = 0; j < cands.length; j++) { var dx = cands[j].x - e.x, dy = cands[j].y - e.y; if (dx*dx+dy*dy <= t.sp*t.sp) n += Math.min(cands[j].hp, Math.max(1, d - cands[j].armor)); }
          sc = n * 10000 - e.remaining;
        } else if (t.sl) {
          sc = (e.slowed ? 0 : 1e7) + e.maxHp * 10 - e.remaining / 100;
        } else {
          var eff = t.pi ? d : Math.max(1, d - e.armor);
          sc = Math.min(eff, e.hp) * 10000 - e.remaining;
          if (e.type === "mender") sc += 5000 * 10;
        }
        if (sc > bs) { bs = sc; best = e.id; }
      }
      return best;
    }
  };
}

