var P0 = m[1].split(',').map(Number);
function evalP(P, seeds) {
  eval(src.replace(m[0], 'var P = [' + P.join(',') + '];'));
  var tot = 0; for (var i = 0; i < seeds.length; i++) tot += rampartSimulate(createStrategy, seeds[i], 12020).score;
  return tot / seeds.length;
}
