  for (var c = 0; c < nch; c++) { var k = Math.floor(rnd() * P.length); P[k] = Math.max(0.01, +(P[k] * Math.exp((rnd() - 0.5) * 1.2)).toFixed(3)); }
  var s = evalP(P, seeds);
